def apply(inputs, premises):
    assets = inputs["asset_descriptions"]
    values = inputs["asset_values"]
    kinds = inputs["asset_kinds"]
    plans = []
    for i in range(len(assets)):
        claims = []
        value = values[i]
        kind = kinds[i]
        if inputs["federal_available"]:
            if kind == "domestic_animal":
                claims = claims + [{"citation": inputs["federal_animal_citation"], "claim_value": min(value, inputs["federal_animal_cap"])}]
            if kind == "domestic_animal" or kind == "firearm":
                federal_wildcard_cap = inputs["federal_wildcard_base_cap"] + inputs["federal_unused_homestead_cap"]
                claims = claims + [{"citation": inputs["federal_wildcard_citation"], "claim_value": min(value, federal_wildcard_cap)}]
        if inputs["oregon_available"]:
            if kind == "domestic_animal":
                claims = claims + [{"citation": inputs["oregon_animal_citation"], "claim_value": min(value, inputs["oregon_animal_cap"])}]
            if kind == "domestic_animal" or kind == "firearm":
                claims = claims + [{"citation": inputs["oregon_any_property_citation"], "claim_value": min(value, inputs["oregon_any_property_cap"])}]
            if kind == "firearm":
                claims = claims + [{"citation": inputs["oregon_firearm_citation"], "claim_value": min(value, inputs["oregon_firearm_cap"])}]
        plans = plans + [{"asset": assets[i], "claims": claims}]
    return {"plans": plans}

